const KB = "~/Desktop/agiworkforce/knowledge-base";
const ST = { type: "string", enum: ["built", "partly built", "not built", "does not apply", "page does not say"] };
const OUT = { type: "object", properties: { features: { type: "array", items: { type: "object", properties: { id: { type: "string" }, web: ST, desktop: ST, mobile: ST, cli: ST, vscode: ST, chrome: ST, differs_from_status_table: { type: "array", items: { type: "object", properties: { app: { type: "string" }, table_says: { type: "string" }, page_says: { type: "string" }, quote: { type: "string" } }, required: ["app", "table_says", "page_says", "quote"] } } }, required: ["id", "web", "desktop", "mobile", "cli", "vscode", "chrome", "differs_from_status_table"] } } }, required: ["features"] };
const res = await parallel(JOBS.map((job, n) => () => agent(
  "Read these " + job.length + " pages of a knowledge base. Do not open any other file and do not read code. Pages (id, path under " + KB + "):\n" + job.map((j) => j[0] + "  " + KB + "/" + j[1]).join("\n") + "\n\n" +
  "Each page describes one feature of a product with six apps: Web, Desktop, Mobile, CLI, VS Code, Chrome. Near the top is a 'Status' table whose column 'In the code' comes from an older audit. Sections 2 (User experience: 'Where to find it'), 3 (Current implementation: working, incomplete, disconnected, not available) and 10 (Gaps) are a newer reading of the code.\n" +
  "For each page decide, from sections 2, 3 and 10 ONLY, what the page itself says about each app: 'built' (the page describes it as present and working in the code on that app), 'partly built' (present with parts incomplete, switched off or missing on that app), 'not built' (the page says it is not available or has no code on that app), 'does not apply' (the page says the feature has no meaning on that app), or 'page does not say'. Desktop shows the hosted web app, so when a page says Desktop is the same as Web, give Desktop the Web value.\n" +
  "Then list every app where your value differs from the Status table's 'In the code' column (built, partly built, not built, does not apply), with a short exact quote from the page that supports the page's value. Return one entry per page with its id.",
  { label: "status:" + job[0][0] + "..", phase: "Status", schema: OUT, model: "haiku" }).then((r) => (r ? r.features : []))));
const all = res.filter(Boolean).flat();
log("features read: " + all.length + "; with at least one difference: " + all.filter((f) => f.differs_from_status_table.length).length);
return { features: all };
